namespace sv_7eb65ce5caf64a618e6e889e42268c9c.Services;

public sealed record Recipe(int Id, string Title, string Description, int PrepTimeMinutes);

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomato sauce.", 30),
            new(2, "Spaghetti Carbonara", "Creamy Roman pasta with guanciale, egg yolk, Pecorino Romano, and black pepper.", 25),
            new(3, "Risotto alla Milanese", "Saffron-infused Arborio rice slowly cooked in broth with Parmigiano-Reggiano.", 45),
        },
        [2] = new List<Recipe>
        {
            new(4, "Chicken Tikka Masala", "Tender chicken pieces in a rich, spiced tomato and cream sauce.", 50),
            new(5, "Palak Paneer", "Fresh spinach curry with cubes of soft paneer cheese and aromatic spices.", 35),
            new(6, "Biryani", "Fragrant basmati rice layered with marinated meat, saffron, and caramelized onions.", 60),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Marinated pork on corn tortillas with pineapple, cilantro, and onion.", 40),
            new(8, "Guacamole", "Fresh avocado dip with lime juice, cilantro, jalapeño, and tomato.", 10),
            new(9, "Enchiladas Verdes", "Corn tortillas filled with chicken, topped with tangy tomatillo salsa and cheese.", 45),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        return RecipesByCuisine.TryGetValue(cuisineId, out var recipes)
            ? recipes
            : [];
    }
}

@page "/recipes/{CuisineId:int}"
@using sv_7eb65ce5caf64a618e6e889e42268c9c.Services
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Nav

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<div class="mb-3">
    <a href="/recipes/1?sort=@sort" class="btn btn-outline-primary me-1">Italian</a>
    <a href="/recipes/2?sort=@sort" class="btn btn-outline-primary me-1">Indian</a>
    <a href="/recipes/3?sort=@sort" class="btn btn-outline-primary">Mexican</a>
</div>

<div class="mb-3">
    <label class="form-label fw-bold">Sort by:</label>
    <a href="/recipes/@CuisineId?sort=newest" class="btn btn-sm @(sort == "newest" ? "btn-secondary" : "btn-outline-secondary") me-1">Newest</a>
    <a href="/recipes/@CuisineId?sort=popular" class="btn btn-sm @(sort == "popular" ? "btn-secondary" : "btn-outline-secondary")">Popular</a>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="Retry">Retry</button>
    </div>
}
else if (recipes is null)
{
    <p><em>Loading recipes...</em></p>
}
else
{
    @if (isRefreshing)
    {
        <div class="alert alert-info py-1 px-3" role="status">Refreshing…</div>
    }

    <div class="row row-cols-1 row-cols-md-3 g-4">
        @foreach (var recipe in DisplayRecipes)
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-body-secondary">
                        Prep time: @recipe.PrepTimeMinutes min
                    </div>
                </div>
            </div>
        }
    </div>

    @if (recipes.Count == 0)
    {
        <p class="text-muted mt-3">No recipes found for this cuisine.</p>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? recipes;
    private string? errorMessage;
    private bool isRefreshing;
    private string sort = "newest";
    private int loadedCuisineId;

    private CancellationTokenSource? loadCts;
    private readonly CancellationTokenSource disposeCts = new();

    private IEnumerable<Recipe> DisplayRecipes => sort == "popular"
        ? recipes!.OrderByDescending(r => r.PrepTimeMinutes)
        : recipes!.OrderByDescending(r => r.Id);

    protected override async Task OnParametersSetAsync()
    {
        sort = string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? "popular"
            : "newest";

        if (CuisineId == loadedCuisineId)
            return;

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load.
        await CancelPendingLoadAsync();

        loadCts = CancellationTokenSource.CreateLinkedTokenSource(disposeCts.Token);
        var cts = loadCts;
        var token = cts.Token;

        isRefreshing = recipes is not null;
        errorMessage = null;
        loadedCuisineId = CuisineId;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, token);

            if (token.IsCancellationRequested)
                return;

            recipes = result;
            isRefreshing = false;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Load was intentionally cancelled — nothing to do.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            errorMessage = "The request timed out. Please try again.";
            isRefreshing = false;
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            errorMessage = "Something went wrong while loading recipes. Please try again.";
            isRefreshing = false;
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingLoadAsync()
    {
        if (loadCts is not null)
        {
            await loadCts.CancelAsync();
            loadCts.Dispose();
            loadCts = null;
        }
    }

    public void Dispose()
    {
        disposeCts.Cancel();
        disposeCts.Dispose();
        loadCts?.Dispose();
    }
}

